// Instagram Meta AI Imagine in a direct message thread (2026), the mobile app's dark Direct thread (two third-party phone screen
// recordings on YouTube, 2025-12 and 2026-01; spec .tmp/clone-9e82faf1/reveal-refs/instagram-imagine/spec.json, confidence 0.60;
// frames wy_ig_pend_dm_6p.jpg, wy_ig_pend_zoom.png, wy_ig_land_dm_6p.jpg). Typing '/' in a thread and choosing 'Imagine' makes the
// composer read '@Meta AI /imagine ' and the user sends the prompt as a purple right-aligned bubble. Meta AI answers in the thread:
// above the answer a 'Replied to you' row quotes the prompt, and the answer itself is an EMPTY rounded square media bubble
// (near-flat #060B05) carrying a thin light circular spinner ring (#414640 stroke, one brighter arc turning), with four dimmed round
// action icons (send, download, thumbs up, thumbs down) directly beneath. There is no blur, no file-size pill, no percentage and no
// text inside the bubble; the finished picture then lands sharp in the same square and the four icons become active.
// Adapted to ten images: ten of these Meta AI media bubbles in one reply group, in thread order, five to a row so all ten stay in
// the 560 px frame (the real thread stacks one per prompt and scrolls); all ten arrive empty with their ring and dimmed icons,
// and land one after another in thread order. Omitted: the 'Messages are generated by AI' disclaimer strip, the 'Swipe up to turn
// on disappearing messages' hint, the first-use 'Introducing Meta AI in chats' card, the image viewer's Download button, the
// chat's avatar logo (a plain disc) and the status bar. Every picture is our own meme; no logo, wordmark or platform font is
// drawn (a plain ring, plain squares, system type).
import { press } from '../../../../lib.9b47fc30.js';
import { injectStyle, restTransform, restFilter, ownSrc, UI_FONT } from './util.9e82faf1.js';

const P = 'rv-igi';
const ROOT_H = 468, COLS = 5, GAP = 10;
const ICONS = [
  '<path d="M2.5 7.2L13 2.8 9.2 13.2 7.6 8.6z"/>',
  '<path d="M8 2.5v7.2M4.8 7L8 10.2 11.2 7M3 13h10"/>',
  '<path d="M3 7.5h2.3v6H3zM5.3 7.7L8 2.5c1.2 0 1.7.9 1.4 2L9 6.3h3.6a1 1 0 011 1.2l-.9 4.8a1.5 1.5 0 01-1.5 1.2H5.3"/>',
  '<g transform="rotate(180 8 8)"><path d="M3 7.5h2.3v6H3zM5.3 7.7L8 2.5c1.2 0 1.7.9 1.4 2L9 6.3h3.6a1 1 0 011 1.2l-.9 4.8a1.5 1.5 0 01-1.5 1.2H5.3"/></g>',
];
const CSS = `
.${P} { box-sizing: border-box; display: flex; flex-direction: column; width: 560px; max-width: 100%; height: ${ROOT_H}px; border-radius: 12px; background: #010100; color: #f2f2f2; font-family: ${UI_FONT}; -webkit-font-smoothing: antialiased; overflow: hidden; box-shadow: 0 0 0 1px #1c1c1c; }
.${P}-top { flex: none; display: flex; align-items: center; gap: 10px; height: 42px; padding: 0 16px; }
.${P}-top svg { flex: none; width: 13px; height: 13px; fill: none; stroke: #f2f2f2; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.${P}-av { flex: none; width: 24px; height: 24px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #4a4a4a, #222); }
.${P}-nm { display: flex; flex-direction: column; font-size: 9px; font-weight: 700; line-height: 11px; white-space: nowrap; }
.${P}-nm small { font-size: 6.5px; font-weight: 400; color: #8e8e8e; }
.${P}-ti { margin-left: auto; display: flex; gap: 14px; }
.${P}-th { flex: 1; min-height: 0; box-sizing: border-box; display: flex; flex-direction: column; justify-content: flex-end; padding: 0 16px 12px; overflow: hidden; }
.${P}-me { align-self: flex-end; box-sizing: border-box; max-width: 330px; padding: 8px 12px; border-radius: 16px; background: linear-gradient(135deg, #5b3df5, #a21ad6); font-size: 8.5px; line-height: 12px; color: #fff; }
.${P}-me b { font-weight: 700; }
.${P}-rp { display: flex; align-items: center; gap: 4px; margin: 14px 0 4px; font-size: 7px; color: #8e8e8e; white-space: nowrap; }
.${P}-rp svg { width: 9px; height: 9px; fill: none; stroke: #8e8e8e; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.${P}-qt { align-self: flex-start; box-sizing: border-box; max-width: 250px; padding: 6px 10px; border-radius: 12px; background: #2a1b52; font-size: 7.5px; line-height: 10px; color: #cfc4ee; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.${P}-g { display: grid; grid-template-columns: repeat(${COLS}, minmax(0, 1fr)); gap: 8px ${GAP}px; margin-top: 8px; }
.${P}-m { display: flex; flex-direction: column; gap: 6px; }
.${P}-t { position: relative; aspect-ratio: 1; border-radius: 10px; overflow: hidden; background: #060b05; }
.${P}-t img { position: absolute; inset: 0; display: block; width: 100%; height: 100%; object-fit: cover; }
.${P}-pend { position: absolute; inset: 0; display: grid; place-items: center; background: #060b05; }
.${P}-ring { display: block; width: 26px; height: 26px; border-radius: 50%; background: conic-gradient(from 0deg, #a4aaa3 0deg, #8f958f 60deg, #414640 120deg, #414640 360deg); -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 1.8px), #000 calc(100% - 1.3px)); mask: radial-gradient(farthest-side, transparent calc(100% - 1.8px), #000 calc(100% - 1.3px)); }
.${P}-ac { display: flex; justify-content: space-between; padding: 0 1px; }
.${P}-ac i { display: grid; place-items: center; width: 17px; height: 17px; border-radius: 50%; background: #1b1b1b; }
.${P}-ac svg { width: 9px; height: 9px; fill: none; stroke: #f2f2f2; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.${P}-cp { flex: none; display: flex; align-items: center; gap: 8px; height: 46px; padding: 0 14px 6px 12px; }
.${P}-cam { flex: none; width: 26px; height: 26px; border-radius: 50%; background: #3797f0; }
.${P}-fl { flex: 1; display: flex; align-items: center; justify-content: space-between; box-sizing: border-box; height: 28px; padding: 0 12px; border-radius: 14px; background: #1c1c1c; font-size: 8px; color: #8e8e8e; }
.${P}-fl span { display: flex; gap: 8px; }
.${P}-fl u { display: block; width: 9px; height: 9px; box-sizing: border-box; border: 1.3px solid #d4d4d4; border-radius: 3px; }
.${P}-fl u.${P}-c { border-radius: 50%; }
`;

const PROMPT = 'a muse holding a handwritten note in a lecture hall, meme style';
const REF = 1.84;                                 // the beat in seconds from the card's entrance: cardIn .. lastLand, stretched with the real window
const SEND_AT = 0.04;                             // the purple '@Meta AI /imagine' bubble is sent
const REPLY_AT = 0.14;                            // the 'Replied to you' row and quoted prompt appear
const ARRIVE = (i) => 0.16 + i * 0.02;            // layout second bubble i appears in the thread, empty with its ring (all before the first landing at 0.41)
const svg = (p) => `<svg viewBox="0 0 16 16">${p}</svg>`;

export default {
  id: 'instagram-imagine',
  label: 'Instagram Meta AI Imagine (2026)',
  source: {
    platform: "Instagram Direct (mobile app, dark theme): '@Meta AI /imagine' in a message thread, Meta AI's in-thread image reply (two third-party phone screen recordings on YouTube, 2025-12 and 2026-01)",
    feature: "each image arrives as an EMPTY rounded square in-thread bubble with a thin rotating spinner ring and four dimmed round action icons (send, download, thumbs up, thumbs down) beneath, a 'Replied to you' row quoting the prompt above; no blur, no file-size pill, no text; the picture then lands sharp in the same square and the icons become active (adapted to 10: ten bubbles in one reply group, five to a row, landing in thread order)",
    refs: [
      { url: 'https://www.youtube.com/watch?v=HDA06TosUcA', retrieved: '2026-10-14' },
      { url: 'https://www.youtube.com/watch?v=6pJaYmCAYJE', retrieved: '2026-10-14' },
    ],
    extrapolated: "The real thread holds one square per prompt and scrolls: ten bubbles in one Meta AI reply group, five to a row so all ten fit the 560 px frame, arriving empty within a fraction of a second and landing one after another in thread order, the hard swap (the 2026-01 clip ramps the square over ~0.23 s, which may be the recording's own dissolve) and the icons turning active one bubble at a time are extrapolated; the prompt text, header and composer row are indicative.",
  },
  build(x, ctx) {
    injectStyle(P, CSS);
    const { tiles } = ctx;
    const src = ownSrc(ctx.src, 'instagram-imagine');
    const acts = ICONS.map((p) => `<i>${svg(p)}</i>`).join('');
    const cell = (g, i) => `<div class="${P}-m" style="visibility: hidden"><div class="${P}-t"><img src="${src}" width="870" height="1024" decoding="sync" alt="Muse meme ${i + 1}" style="visibility: hidden; transform-origin: ${g.origin}"/><div class="${P}-pend"><i class="${P}-ring"></i></div></div><div class="${P}-ac" style="opacity: 0.32">${acts}</div></div>`;
    const back = '<svg viewBox="0 0 16 16"><path d="M10 2.5L4.5 8 10 13.5"/></svg>';
    const call = '<svg viewBox="0 0 16 16"><path d="M3.5 2.5h2.5l1 3-1.6 1.1a8 8 0 003.5 3.5L10 8.5l3 1v2.5a1.5 1.5 0 01-1.6 1.5A9.5 9.5 0 012 4.1 1.5 1.5 0 013.5 2.5z"/></svg>';
    const vid = '<svg viewBox="0 0 16 16"><rect x="1.5" y="4" width="9" height="8" rx="2"/><path d="M10.5 7l4-2v6l-4-2"/></svg>';
    const info = '<svg viewBox="0 0 16 16"><circle cx="8" cy="8" r="6"/><path d="M8 7.2v3.6M8 5.2v.2"/></svg>';
    const rep = '<svg viewBox="0 0 16 16"><path d="M6.5 3L2.5 7l4 4M2.5 7h7a4 4 0 014 4v1.5"/></svg>';
    const root = x.el(`<div class="${P}"><div class="${P}-top">${back}<div class="${P}-av"></div><div class="${P}-nm">Meta AI<small>AI</small></div><div class="${P}-ti">${call}${vid}${info}</div></div><div class="${P}-th"><div class="${P}-me" style="visibility: hidden"><b>@Meta AI /imagine</b> ${x.esc(PROMPT)}</div><div class="${P}-rp" style="visibility: hidden">${rep}Replied to you</div><div class="${P}-qt" style="visibility: hidden">@Meta AI /imagine ${x.esc(PROMPT)}</div><div class="${P}-g">${tiles.map(cell).join('')}</div></div><div class="${P}-cp"><div class="${P}-cam"></div><div class="${P}-fl">Message...<span><u class="${P}-c"></u><u></u><u class="${P}-c"></u><u></u></span></div></div></div>`);
    const me = root.querySelector(`.${P}-me`), rp = root.querySelector(`.${P}-rp`), qt = root.querySelector(`.${P}-qt`);
    const cells = [...root.querySelectorAll(`.${P}-m`)].map((n, i) => ({ n, im: n.querySelector('img'), pend: n.querySelector(`.${P}-pend`), ring: n.querySelector(`.${P}-ring`), ac: n.querySelector(`.${P}-ac`), g: tiles[i] }));
    ctx.gate(cells.map((c) => c.im));
    cells.forEach((c) => { c.im.style.filter = restFilter(c.g); c.im.style.transform = restTransform(c.g); });

    // memoised writes: the DOM is set from t alone, so a seek lands on the same state whatever came before
    const memo = new Map();
    const put = (key, v, fn) => { if (memo.get(key) !== v) { memo.set(key, v); fn(v); } };

    return {
      root,
      render(t) {
        const k = (ctx.lastLand - ctx.cardIn) / REF;   // the beat's window against the layout above
        const s = (t - ctx.cardIn) / k;                // layout seconds since the card entered

        // the prompt is sent (a small press-in), then Meta AI's reply row appears
        const sp = press(s, SEND_AT, 0.05, 0.03, 0.1);
        put('me', `${s >= SEND_AT}${sp.toFixed(3)}`, () => { me.style.visibility = s >= SEND_AT ? '' : 'hidden'; me.style.transform = sp > 0 ? `scale(${(1 - 0.03 * sp).toFixed(4)})` : 'none'; });
        put('rp', s >= REPLY_AT, (v) => { rp.style.visibility = v ? '' : 'hidden'; qt.style.visibility = v ? '' : 'hidden'; });

        cells.forEach((c, i) => {
          put(`a${i}`, s >= ARRIVE(i), (v) => { c.n.style.visibility = v ? '' : 'hidden'; });
          const done = t >= ctx.seq(i)[1];             // the picture lands sharp in the empty square, strictly in thread order
          put(`i${i}`, done, (v) => { c.im.style.visibility = v ? 'visible' : 'hidden'; c.pend.style.display = v ? 'none' : 'grid'; c.ac.style.opacity = v ? '1' : '0.32'; });
          // the ring turns with t (its phase differs per bubble); a function of t alone
          const deg = (((t * 420 + i * 53) % 360) + 360) % 360;
          put(`r${i}`, deg.toFixed(0), (d) => { c.ring.style.transform = `rotate(${d}deg)`; });
        });
      },
    };
  },
};
